// TH18 v1.00a st03.ecl.txt:1071-1085 MainSub00 (wave 1).
// Enemies: GirlRedA01 S:893-903 -> GirlA01 S:77-167; attack async S:93-166.
// Source wave schedule: 10 rounds, 2 girls per round, x=160 decreasing 32,
// y=-48+RANDF2*32 per girl, 30-frame round interval.
const TIME_LIMIT: int = 900; // 120 frame shell buffer + 600 frame source slot + 180 tail
const SOURCE_LIMIT: int = 600; // MainSub00 300 + MainFront wait(300); no explicit source timeout
const TH18_RICE: int = 480; // TH18 type8

// S:93-166 GirlA01_at. Rank-selected etCount/etAngle/etSpeed after stack restore.
async sub girl_burst() {
    var rank: int = global(GVAR_RANK);
    var first: int = 60; // S:96-104 !E/!N 60
    if rank >= 2 { first = 3; } // S:100-103 !H/!LO 3

    wait(first);
    var ways: int = 3;      // S:126 etCount N: E/N 3
    var layers: int = 1;    // S:126 etCount M: E/N 1
    var spread: angle = 30deg; // S:136 etAngle delta 0.523599
    var s0: fx = 2fx;       // S:154 etSpeed s0: E/N 2.0
    var s1: fx = 1fx;       // S:154 etSpeed s1: E/N 1.0
    var volleys: int = 3;   // S:156 diffI($A,3,3,5,6)
    if rank == 2 {          // S:130/141/149-150 H: 3 ways, 2 layers, 30deg, 3.0->2.0
        layers = 2;
        s0 = 3fx;
        s1 = 2fx;
        volleys = 5;
    }
    if rank == 3 {          // S:132/143/151-152 LO: 5 ways, 2 layers, 25deg, 3.0->2.0
        ways = 5;
        layers = 2;
        spread = 25deg;
        s0 = 3fx;
        s1 = 2fx;
        volleys = 6;
    }

    var step: fx = 0fx;
    if layers > 1 { step = s1 - s0; } // v(q)=s0+(s1-s0)*q/(M-1)

    sh_reset(0);
    sh_sprite(0, TH18_RICE, 6); // S:108 etSprite(0,8,6)
    sh_ring(0, 0);
    sh_aim(0, 1);               // S:107 etAim(0,0) aimed fan
    sh_count(0, ways, layers);
    sh_angle(0, 0deg, spread);
    sh_speed(0, s0, step);

    var fired: int = 0;
    loop {
        // S:159-161 Easy skips 2/3 of the volleys; N/H/L always fire.
        if rank == 0 {
            if rand(3) == 0 { sh_fire(0); }
        } else {
            sh_fire(0);
        }
        fired = fired + 1;
        if fired >= volleys { return; }
        wait(45); // S:162 wait(45)
    }
}

// S:77-167 GirlA01 body + movement; GirlRedA01 S:893-903 wrapper is visual/drop only.
async sub girl_main() {
    set_invuln(65535);   // training shell: enemies cannot be shot down
    set_hurtbox(12fx);   // S:79 setHurtbox(24,24): native circle uses width*0.5
    set_hitbox(8fx);     // S:80 setHitbox(16,16): native circle uses width*0.5
    spawn girl_burst();  // S:81 @GirlA01_at() async
    move_vel(0, 90deg, 1.8fx, EASE_LINEAR); // S:82 moveVel(pi/2,1.8)
    wait(20);                                // S:83
    // S:84 moveVelTime(120,1,pi/2+RANDF2*0.17453292,0.8); source mode1 = quad in.
    move_vel(120, 90deg + (rand(1821) as angle), 0.8fx, EASE_QUAD_IN);
    loop { wait(1000); } // S:86-89 resident loop
}

// S:1071-1085 MainSub00 creation loop. Created relative to stage origin.
async sub wave() {
    wait(120); // training shell buffer before the source attack starts
    var x: fx = 160fx; // S:1074 %A=160
    var round: int = 0; // S:1075 $B=10
    loop {
        // S:1078-1079 enmCreate("GirlRedA01", +-A, -48+RANDF2*32, 220,1000,2)
        var y1: fx = -48fx + (rand(65536) as fx) * 0.0000152587890625fx;
        var y2: fx = -48fx + (rand(65536) as fx) * 0.0000152587890625fx;
        _ = spawn_enemy(x, y1, 220, 0, 1000, 0, girl_main);
        _ = spawn_enemy(-x, y2, 220, 0, 1000, 0, girl_main);
        x = x - 32fx; // S:1080
        round = round + 1;
        wait(30);     // S:1081; last wait reaches the 300-frame source return
        if round >= 10 { return; } // S:1082-1083 if ($B--)
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1); // carrier only: no body collision, at (0,0)
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
